from pathlib import Path
import struct
# 无标题4.mgbx 节点数 = 303 (之前实测), 表格3 165节点是'一级加载'工况输出, 不等于节点总数
# 试所有 mgbx, 报告节点数 + 首末节点坐标
def parse(f):
    raw = Path(f).read_bytes()
    # 段目录每项 20B: [tag4][cnt?4][off4][len4][?4], 从 16 起
    i = 16
    n_entry = struct.unpack('<I', raw[12:16])[0]  # 20
    segs = {}
    for k in range(n_entry):
        tag = raw[i:i+4].decode('latin-1')
        cnt = struct.unpack('<I', raw[i+4:i+8])[0]
        off = struct.unpack('<I', raw[i+8:i+12])[0]
        ln = struct.unpack('<I', raw[i+12:i+16])[0]
        unk = struct.unpack('<I', raw[i+16:i+20])[0]
        segs[tag] = (cnt, off, ln, unk)
        i += 20
    data_base = i
    out = {}
    for tag, (cnt, off, ln, unk) in segs.items():
        if tag in ('NODE', 'ELEM'):
            seg = raw[data_base+off:data_base+off+ln]
            out[tag] = (cnt, off, ln, len(seg))
    return out

for f in ['无标题4.mgbx', '无标题.mgbx', '无标2题.mgbx', '无标题.jjmgbx.mgbx']:
    try:
        r = parse(f)
        print(f, r)
    except Exception as e:
        print(f, 'ERR', e)
" 2>&1 | Out-String"}

